// import IMask from 'imask'
import { nameEventForm } from './form-state-control.js'

function toggleCompleted(mask, input) {
  mask.on('complete', function () {
    input.setAttribute('data-valid-mask', 'true')
  })

  mask.on('accept', function () {
    input.setAttribute('data-valid-mask', 'false')
  })
}

function resetValue(input) {
  input.value = ''
}

function updateValue(mask) {
  mask.updateValue()
}

function resetCompleted(input) {
  input.dataset.completed = 'false'
}

export const presetMaskOptions = {
  number: {
    mask: '+{7} (000) 000-00-00',
    lazy: true,
    prepare: (appended, masked) => {
      if (appended === '8' && masked.value === '') {
        return ''
      }
      return appended
    }
  },
  date: {
    mask: Date,
    min: new Date(1990, 0, 1),
    max: new Date(2020, 0, 1),
    lazy: true
  },
  expireDate: {
    mask: Date,
    pattern: 'd.`m.`Y', // Определяем шаблон даты
    // lazy: false, // Оставляет плейсхолдер для всех символов
    blocks: {
      d: {
        mask: IMask.MaskedRange,
        from: 1,
        to: 31,
        maxLength: 2
      },
      m: {
        mask: IMask.MaskedRange,
        from: 1,
        to: 12,
        maxLength: 2
      },
      Y: {
        mask: IMask.MaskedRange,
        from: 2000, // Минимальный год
        to: 2050 // Максимальный год
      }
    },
    format: function (date) {
      const day = date.getDate()
      const month = date.getMonth() + 1 // Месяцы начинаются с 0
      const year = date.getFullYear()
      return [day, month, year]
        .map((val) => String(val).padStart(2, '0'))
        .join('.')
    },
    parse: function (str) {
      const dayMonthYear = str.split('.')
      return new Date(dayMonthYear[2], dayMonthYear[1] - 1, dayMonthYear[0])
    }
  },
  docNumber: {
    mask: '000 000 000', // Шаблон маски
    blocks: {
      // Настройка блоков для маски
      0: {
        mask: IMask.MaskedRange,
        from: 0,
        to: 9,
        maxLength: 1
      }
    }
  }
}

function initialMasked(input, options) {
  const mask = new IMask(input, options)

  const reset = () => {
    resetValue(input)
    resetCompleted(input)
    updateValue(mask)
  }

  toggleCompleted(mask, input)

  input.addEventListener(nameEventForm.reset, () => {
    reset()
  })

  return {
    mask,
    reset
  }
}

export { initialMasked }
