document.addEventListener('DOMContentLoaded', () => {
  const block = document.querySelector('.y-map');
  if (!block) return
  const mapContainer = block.querySelector('#map');
  const mapWrap = block.querySelector('.y-map__wrap');
  const loader = block.querySelector('.y-map__loader');

  const initial = () => {
    const myMap = new ymaps.Map('map', {
      center: [55.746841, 37.690192],
      zoom: 15,
      controls: []
    });

    const myPlacemark = new ymaps.Placemark([55.746841, 37.690192], {
      hintContent: 'Главный офис',
      balloonContent: 'Россия, г. Москва, 111024 шоссе Энтузиастов, д. 2'
    }, {
      iconLayout: 'default#image',
      iconImageSize: [30, 30], // Размер иконки
      iconImageOffset: [-15, -30] // Смещение иконки
    });
    myMap.geoObjects.add(myPlacemark);
    myMap.behaviors.disable('scrollZoom');
  };

  let mapInit = false;

  mapContainer.addEventListener('mouseenter', () => {
    if (!mapInit) {
      mapInit = true;
      loader.classList.add('y-map__loader--active'); // Показываем индикатор загрузки

      loadMap(
        'https://api-maps.yandex.ru/2.1/?lang=ru_RU&loadByRequire=1&apikey=1c43b794-9f2d-419e-b7b8-aae259ee8651',
        (script) => {
          console.log('modal map loaded');
          ymaps.ready(() => {
            initial(); // Инициализируем карту
            loader.classList.remove('y-map__loader--active'); // Скрываем индикатор загрузки
            mapWrap.style.background = 'none'; // Убираем фоновый стиль
          });
        }
      );
    }
  }, { once: true });

  function loadMap(src, callback) {
    let script = document.createElement('script');
    script.src = src;
    script.type = 'text/javascript';
    script.onload = () => callback(script);
    mapContainer.appendChild(script); // Добавляем скрипт в head
  }
});

